/* Бизнес-центры: чек-лист «Здание, готовое к роботам» — считает отмеченные пункты и меняет вывод в штампе.
   Без JS чек-лист остаётся списком с исходным текстом вывода. */
(window.i18n ? window.i18n.ready : Promise.resolve()).then(() => {
  'use strict';
  /* i18n:ru begin (generated by tools/i18n/embed.mjs from i18n/ru.json: the Russian text of the messages this script shows; do not edit) */
  const RU = (() => {
    const nf = new Intl.NumberFormat('ru', { useGrouping: 'always' });
    const n = (x, d) => (d === undefined ? nf : new Intl.NumberFormat('ru', { useGrouping: 'always', minimumFractionDigits: d, maximumFractionDigits: d })).format(x);
    return {
      n,
      m: {
        'js.industryBusinessCenters.verdict.ready': () => 'Здание готово по стандарту MR. Можно сразу планировать пилот на нескольких этажах и паркинге.',
        'js.industryBusinessCenters.verdict.almost': (v) => `Почти готово. Не хватает одного: ${v.missing}. Пилот можно начинать, доработку планируем параллельно.`,
        'js.industryBusinessCenters.verdict.partial': (v) => `Готово частично. Пилот начнём в зонах, где всё есть. Не хватает: ${v.missing} — план доработок дадим после аудита.`,
        'js.industryBusinessCenters.verdict.start': () => 'Здание к роботам почти не готовили. Это обычная ситуация: начнём с одной зоны, например лобби или одного этажа, и составим план доработок на аудите.',
      },
    };
  })();
  // N: a number as the site writes it in the current language; t: a message, English from the dictionary, else Russian from RU
  const N = (x, d) => (i18n.n || RU.n)(x, d);
  const t = (key, v) => { const s = i18n.t(key, v); return s === undefined ? RU.m[key](v) : s; };
  /* i18n:ru end */

  const list = document.querySelector('[data-ready]');
  if (!list) return;
  const boxes = [...list.querySelectorAll('input[type="checkbox"]')];
  const count = document.querySelector('[data-ready-n]');
  const verdict = document.querySelector('[data-ready-verdict]');
  const bars = [...document.querySelectorAll('.bcr__bar i')];
  const stamp = document.querySelector('.bcr__stamp');
  const intro = verdict.textContent;
  // The titles are written into a sentence: the first letter becomes lower-case in Russian only (English has names such as Wi-Fi)
  const lower = (c) => (i18n.lang === 'ru' ? c.toLowerCase() : c);
  const title = (b) => b.closest('.bcr__i').querySelector('b').textContent.replace(/^\d+ · /, '').replace(/^./, lower);

  const text = (n, missing) => {
    const total = boxes.length;
    if (n === 0) return intro;
    if (n === total) return t('js.industryBusinessCenters.verdict.ready');
    const what = missing.map(title).join(', ');
    if (n >= total - 1) return t('js.industryBusinessCenters.verdict.almost', { missing: what });
    if (n >= 2) return t('js.industryBusinessCenters.verdict.partial', { missing: what });
    return t('js.industryBusinessCenters.verdict.start');
  };

  const render = () => {
    const missing = boxes.filter((b) => !b.checked);
    const n = boxes.length - missing.length;
    count.textContent = n;
    bars.forEach((b, i) => b.classList.toggle('on', i < n));
    stamp.dataset.level = n === boxes.length ? 'ready' : n >= 2 ? 'part' : n ? 'start' : '';
    verdict.textContent = text(n, missing);
  };

  list.addEventListener('change', render);
  render();
});
